export const ENGINE_CSS = "/*\n * Layer engine — how deep a thing is, and what that makes it. Hand-authored.\n *\n * ONE axis lives here: elevation.\n *\n *   --itx-surface / -above / -above-2 / -below — the neutral substrate,\n *   backgrounds only, moving toward light in BOTH schemes.\n *\n * Everything drawn ON a surface is a palette step from themes/…/ladder.css.\n * Steps are absolute, so nothing here has to re-derive them per layer — which\n * is why this file is a counter and four formulas rather than a table.\n *\n * ── Why this file looks the way it does ─────────────────────────────────\n *\n * An inherited custom property CANNOT increment itself. `--x: calc(var(--x)\n * + 1)` is a self-cycle, and a chain of slots re-declared in one block all\n * resolve against the SAME element, so it collapses to whichever slot the\n * block did not redeclare. The previous sliding-window implementation did\n * exactly that and never worked; see elevation-legacy.spec.ts.\n *\n * @container style() is the way out: a container query is evaluated against\n * the nearest ANCESTOR container, never the element itself, so there is no\n * cycle. Every element is a style container by default, so no container-type\n * is needed, and because --itx-layer inherits it compounds correctly through\n * arbitrary intermediate DOM.\n *\n * Three tiers, in source order — everything is :where() zero-specificity and\n * @container adds none, so later simply wins:\n *\n *   1. Layer 0, unconditional. NOT inside @container: if [interop-root] is\n *      <html> it has no ancestor container and the query is never known.\n *   2. A one-step floor for [itx-layer] / [itx-sink]. Browsers without style\n *      queries stop here — one step, not compounding, which is a defensible\n *      degradation rather than a broken page.\n *   3. The counter, unrolled. Overrides tier 2 wherever it is supported.\n *\n * Adding a layer means adding a @container block AND an absolute pin. That is\n * the one part of the colour system that cannot be a custom property, and\n * scripts/generate-globals.mjs signposts it for exactly that reason.\n *\n * Absolute pins come last so they outrank the counter — a dialog must not\n * inherit its depth from wherever it happens to sit in the DOM.\n *\n * If toggle() ever ships, tiers 2 and 3 collapse to one declaration:\n *   --itx-layer: toggle(0, 1, 2, 3, 4);\n */\n\n@property --itx-layer {\n\tsyntax: \"<integer>\";\n\tinherits: true;\n\tinitial-value: 0;\n}\n\n/*\n * Registered as <color> deliberately. An unregistered custom property that\n * goes invalid becomes the guaranteed-invalid value, which INHERITS and takes\n * the whole subtree down with it. Registered, a broken layer degrades to the\n * parent surface instead — and surfaces become transition-able between layers.\n */\n@property --itx-surface {\n\tsyntax: \"<color>\";\n\tinherits: true;\n\tinitial-value: transparent;\n}\n\n/* ── Tier 1 — layer 0, unconditional ─────────────────────────────────── */\n\n:where([interop-root], [itx-layer], [itx-sink]) {\n\t--itx-surface: light-dark(\n\t\toklch(clamp(\n\t\t\t\tvar(--itx-ramp-light-min),\n\t\t\t\tcalc(var(--itx-ramp-light-page) + var(--itx-ramp-light-step) * var(--itx-layer)),\n\t\t\t\tvar(--itx-ramp-light-max)\n\t\t\t) var(--itx-tint-light)),\n\t\toklch(clamp(\n\t\t\t\tvar(--itx-ramp-dark-min),\n\t\t\t\tcalc(var(--itx-ramp-dark-page) + var(--itx-ramp-dark-step) * var(--itx-layer)),\n\t\t\t\tvar(--itx-ramp-dark-max)\n\t\t\t) var(--itx-tint-dark))\n\t);\n\t--itx-surface-above: light-dark(\n\t\toklch(clamp(\n\t\t\t\tvar(--itx-ramp-light-min),\n\t\t\t\tcalc(var(--itx-ramp-light-page) + var(--itx-ramp-light-step) * max(0, calc(var(--itx-layer) + 1))),\n\t\t\t\tvar(--itx-ramp-light-max)\n\t\t\t) var(--itx-tint-light)),\n\t\toklch(clamp(\n\t\t\t\tvar(--itx-ramp-dark-min),\n\t\t\t\tcalc(var(--itx-ramp-dark-page) + var(--itx-ramp-dark-step) * max(0, calc(var(--itx-layer) + 1))),\n\t\t\t\tvar(--itx-ramp-dark-max)\n\t\t\t) var(--itx-tint-dark))\n\t);\n\t--itx-surface-above-2: light-dark(\n\t\toklch(clamp(\n\t\t\t\tvar(--itx-ramp-light-min),\n\t\t\t\tcalc(var(--itx-ramp-light-page) + var(--itx-ramp-light-step) * max(0, calc(var(--itx-layer) + 2))),\n\t\t\t\tvar(--itx-ramp-light-max)\n\t\t\t) var(--itx-tint-light)),\n\t\toklch(clamp(\n\t\t\t\tvar(--itx-ramp-dark-min),\n\t\t\t\tcalc(var(--itx-ramp-dark-page) + var(--itx-ramp-dark-step) * max(0, calc(var(--itx-layer) + 2))),\n\t\t\t\tvar(--itx-ramp-dark-max)\n\t\t\t) var(--itx-tint-dark))\n\t);\n\t--itx-surface-below: light-dark(\n\t\toklch(clamp(\n\t\t\t\tvar(--itx-ramp-light-min),\n\t\t\t\tcalc(var(--itx-ramp-light-page) + var(--itx-ramp-light-step) * max(0, calc(var(--itx-layer) + 1))),\n\t\t\t\tvar(--itx-ramp-light-max)\n\t\t\t) var(--itx-tint-light)),\n\t\toklch(clamp(\n\t\t\t\tvar(--itx-ramp-dark-min),\n\t\t\t\tcalc(var(--itx-ramp-dark-page) + var(--itx-ramp-dark-step) * max(0, calc(var(--itx-layer) + 1))),\n\t\t\t\tvar(--itx-ramp-dark-max)\n\t\t\t) var(--itx-tint-dark))\n\t);\n}\n\n:where([interop-root]) {\n\t--itx-layer: 0;\n\n\tbackground-color: var(--itx-surface);\n\tcolor: var(--itx-neutral-14);\n\n\t/* ── Z-index scale ───────────────────────────────────────────────── */\n\t--itx-z-dropdown: 1000;\n\t--itx-z-sticky: 1020;\n\t--itx-z-fixed: 1030;\n}\n\n/* ── Tier 2 — progressive-enhancement floor (no style queries) ───────── */\n\n:where([itx-layer]) {\n\t--itx-layer: 1;\n}\n\n:where([itx-sink]) {\n\t--itx-layer: 1;\n}\n\n/* ── Tier 3 — the counter. Strictly monotone up the tree, so never a cycle. */\n\n@container style(--itx-layer: 0) {\n\t:where([itx-layer]) {\n\t\t--itx-layer: 1;\n\t}\n\n\t:where([itx-sink]) {\n\t\t--itx-layer: 1;\n\t}\n}\n\n@container style(--itx-layer: 1) {\n\t:where([itx-layer]) {\n\t\t--itx-layer: 2;\n\t}\n\n\t:where([itx-sink]) {\n\t\t--itx-layer: 2;\n\t}\n}\n\n@container style(--itx-layer: 2) {\n\t:where([itx-layer]) { /* terminal — re-asserts without moving */\n\t\t--itx-layer: 2;\n\t}\n\n\t:where([itx-sink]) { /* terminal — re-asserts without moving */\n\t\t--itx-layer: 2;\n\t}\n}\n\n/* ── Absolute pins — last, so they outrank the counter ───────────────── */\n\n:where([itx-layer=\"0\"]) {\n\t--itx-layer: 0;\n}\n\n:where([itx-layer=\"1\"]) {\n\t--itx-layer: 1;\n}\n\n:where([itx-layer=\"2\"]) {\n\t--itx-layer: 2;\n}\n\n/* ── Paint. Zero specificity, so any consumer rule wins on contact. ──── */\n\n:where([itx-layer], [itx-sink]) {\n\tbackground-color: var(--itx-surface);\n\tcolor: var(--itx-neutral-14);\n}\n\n/*\n * Direction. Tone already said how FAR from the page a surface is; these\n * say which way, which is the half of the model tone used to carry.\n *\n * A layer and a sink at the same depth are the same colour on purpose —\n * light from above is what separates them, so a raise casts a shadow and a\n * recess is shadowed within. Zero specificity, so a component that paints\n * its own box-shadow wins on contact and nothing here needs unwinding.\n */\n:where([itx-layer]) {\n\tbox-shadow: var(--itx-elevation-shadow);\n}\n\n:where([itx-sink]) {\n\tbox-shadow: var(--itx-recess-shadow);\n}\n";
